/**
 * The shape of a pinned SimulationCraft APL authority artifact, and a runtime
 * validator for it.
 *
 * The artifact is generated by `scripts/authority/extract-simc-apl.mjs` from one
 * exact commit and committed. Nothing here reaches the network, and nothing here
 * parses C++.
 *
 * WHY A RUNTIME VALIDATOR FOR AN IMPORTED JSON FILE
 *
 * `resolveJsonModule` gives the import a structural type inferred from the file
 * on disk, which is not the same as a checked contract: a regenerated artifact
 * with a missing field would either fail to compile in a confusing place or slip
 * through as a widened type. Validating explicitly means a malformed artifact
 * fails closed at load with a reason, in the same style as every other boundary
 * in this codebase.
 *
 * WHAT THE ARTIFACT STORES, AND WHAT IT DELIBERATELY DOES NOT
 *
 * It stores `actionStringVerbatim`: the exact first string argument passed to
 * `add_action` in the source. It is NOT a synthesized `actions+=/...` line —
 * the source contains no such line, and calling a synthesized string "verbatim"
 * would be a false provenance claim.
 *
 * It does NOT store `actionToken`, `conditionRaw` or `callsListName`. Those are
 * derived from the verbatim string at load time, so there is exactly one source
 * of truth and "derived fields are reproducible from the verbatim string" holds
 * by construction rather than by a test that could drift.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_ARTIFACT_VERSION = 1;

/**
 * How the extractor located the region, for a target that selects it by
 * SOURCE COORDINATES rather than by marker lines (M11-C1a).
 *
 * The line `namespace <enclosingNamespace>` occurs once in the pinned file;
 * the region is the body of the one function whose header line equals
 * `functionHeader` inside that namespace; its list declarations are read on
 * `playerIdentifier` (`player->get_action_priority_list`). No marker line
 * exists in such a file, so none is recorded: this selector is the whole
 * claim, and the source hash pins the bytes it was applied to.
 */
export interface AuthorityNamespaceFunctionSelector {
  readonly kind: "NAMESPACE_FUNCTION";
  readonly enclosingNamespace: string;
  readonly functionHeader: string;
  readonly playerIdentifier: string;
}

/**
 * A list built by a CLASS METHOD rather than by a free function (ONB-B2): the one definition
 * of `functionHeader` at file scope. It reads lists on its own `this`, so no player identifier
 * is recorded, and no marker line exists.
 */
export interface AuthorityClassMethodSelector {
  readonly kind: "CLASS_METHOD";
  readonly enclosingClass: string;
  readonly functionHeader: string;
}

/**
 * A list held in its own file with no markers, `#include`d as the sole body of `functionHeader`
 * in another pinned file (ONB-C1). The whole source file is the region, and the including file's
 * hash and include line are the claim that it is that function's body.
 */
export interface AuthorityIncludedFileSelector {
  readonly kind: "INCLUDED_FILE";
  readonly includingSourcePath: string;
  readonly includingSourceSha256: string;
  readonly includeLine: string;
  readonly functionHeader: string;
}

/** Every selector kind this build accepts. A marker-selected artifact carries NO selector. */
export const AUTHORITY_REGION_SELECTOR_KINDS = [
  "NAMESPACE_FUNCTION",
  "CLASS_METHOD",
  "INCLUDED_FILE",
] as const satisfies readonly (
  AuthorityNamespaceFunctionSelector | AuthorityClassMethodSelector | AuthorityIncludedFileSelector
)["kind"][];

/**
 * The region's provenance, in exactly ONE of two forms (M11-C1a):
 *
 *   MARKER LINES       `regionStartMarker` / `regionEndMarker` are the literal
 *                      marker comment lines (`//blood_apl_start`, …) the
 *                      region lay between. Every artifact before M11-C1a has
 *                      this form, unchanged in meaning and in bytes.
 *   NAMESPACE_FUNCTION `regionSelector` records the source coordinates, and
 *                      NEITHER marker field is present — a namespace boundary
 *                      is not a marker and is never written into one.
 *
 * An artifact carrying both, or a partial form of either, is malformed.
 */
export type AuthorityRegionProvenance =
  | {
      readonly regionStartMarker: string;
      readonly regionEndMarker: string;
      readonly regionSelector?: never;
    }
  | {
      readonly regionSelector:
        AuthorityNamespaceFunctionSelector | AuthorityClassMethodSelector | AuthorityIncludedFileSelector;
      readonly regionStartMarker?: never;
      readonly regionEndMarker?: never;
    };

export type AuthorityArtifactProvenance = AuthorityArtifactProvenanceCommon & AuthorityRegionProvenance;

interface AuthorityArtifactProvenanceCommon {
  readonly repository: string;
  readonly branch: string;
  /** The exact pinned commit. Never a branch name at runtime. */
  readonly commitSha: string;
  readonly commitDate: string;
  readonly sourcePath: string;
  readonly sourceSha256: string;
  readonly sourceByteLength: number;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  /**
   * What the extractor DECIDED about client-version guards in the region
   * (M11-B2), when the target evaluated any. A pinned region may carry both
   * sides of a patch transition; the artifact's lists hold only the side that
   * holds at the target's client version, and this record says which lines
   * were dropped and why, so an absent line is never mistaken for one that
   * was never in the source. Absent on artifacts whose region has no guard.
   */
  readonly conditionalCompilation?: AuthorityConditionalCompilation;
  /**
   * What ties a PINNED target's artifact back to its extraction record
   * (M11-D2-C): the region's own bytes, the live/PTR policy that chose the
   * region, the class module that dispatches to it, and every statement the
   * region parser was told to treat as inert. All present or all absent;
   * absent on every artifact extracted before M11-D2-C.
   */
  readonly regionSha256?: string;
  readonly livePtrPolicy?: AuthorityLivePtrPolicy;
  readonly dispatchSource?: { readonly sourcePath: string; readonly sourceSha256: string };
  readonly inertStatements?: readonly AuthorityInertStatement[];
  /**
   * The guard a class method opens on (ONB-B2), when it has one: the lists below it exist only
   * when `appliesWhen` holds, and the artifact is the list of a player it holds for.
   */
  readonly methodPrologue?: AuthorityMethodPrologue;
  /**
   * What the extractor DECIDED about each `add_action( this, "<Name>", ... )` statement (ONB-B2).
   * That form emits only under the player's own spell data, so `emitted` null means the line
   * does not exist at this pin, never that it was missed.
   */
  readonly spellGatedActions?: readonly AuthoritySpellGatedAction[];
}

/** The lines of a method's opening guard, and what must hold for the lists to exist. */
export interface AuthorityMethodPrologue {
  readonly startLine: number;
  readonly endLine: number;
  readonly appliesWhen: string;
}

/** One spell-gated statement and the list line it produces, or `null` for none. */
export interface AuthoritySpellGatedAction {
  readonly sourceLine: number;
  readonly statement: string;
  readonly spellName: string;
  readonly emitted: string | null;
}

/** How a pinned target's live region relates to a PTR region at the pin (M11-D2-C). */
export type AuthorityLivePtrPolicy =
  "NO_PTR_REGION" | "PTR_MARKERS_EMPTY" | "PTR_BODY_IDENTICAL" | "PTR_SEPARATE_INCLUDE";

export const AUTHORITY_LIVE_PTR_POLICIES = [
  "NO_PTR_REGION",
  "PTR_MARKERS_EMPTY",
  "PTR_BODY_IDENTICAL",
  "PTR_SEPARATE_INCLUDE",
] as const satisfies readonly AuthorityLivePtrPolicy[];

/** One region statement the extractor dropped as proven inert, by exact text. */
export interface AuthorityInertStatement {
  readonly sourceLine: number;
  readonly statement: string;
  readonly identifier: string;
}

export interface AuthorityVersionGuardRecord {
  readonly line: number;
  readonly form: "IF" | "ELSE_IF";
  /** `wowv() <op> a.b.c`, verbatim from the extractor. */
  readonly comparison: string;
  readonly clientVersion: string;
  readonly holds: boolean;
  readonly statementsEmitted: number;
  readonly statementsDropped: number;
  readonly endLine: number | null;
}

export interface AuthorityConditionalCompilation {
  readonly clientVersion: string;
  readonly guards: readonly AuthorityVersionGuardRecord[];
}

export interface AuthorityArtifactAction {
  readonly priorityOrdinal: number;
  /** The exact first string argument to `add_action` in the pinned source. */
  readonly actionStringVerbatim: string;
  /** The optional second argument. `null` when the source supplied none. */
  readonly comment: string | null;
  readonly sourceLine: number;
}

export interface AuthorityArtifactList {
  readonly listName: string;
  /** The C++ variable the source used, e.g. `default_` for list `default`. */
  readonly receiverIdentifier: string;
  readonly actions: readonly AuthorityArtifactAction[];
}

export interface AuthorityArtifact {
  readonly artifactVersion: number;
  readonly authorityId: string;
  readonly artifactRevision: string;
  readonly spec: { readonly className: string; readonly specName: string };
  readonly entryListName: string;
  readonly provenance: AuthorityArtifactProvenance;
  readonly lists: readonly AuthorityArtifactList[];
}

export type ArtifactValidation =
  | { readonly ok: true; readonly artifact: AuthorityArtifact }
  | { readonly ok: false; readonly reason: ArtifactValidationReason; readonly detail: string };

export type ArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "MALFORMED_LISTS"
  | "ENTRY_LIST_MISSING"
  | "DUPLICATE_LIST_NAME"
  | "MALFORMED_ACTION";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function num(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function invalid(reason: ArtifactValidationReason, detail: string): ArtifactValidation {
  return { ok: false, reason, detail };
}

function validateProvenance(value: unknown): AuthorityArtifactProvenance | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const branch = str(value, "branch");
  const commitSha = str(value, "commitSha");
  const commitDate = str(value, "commitDate");
  const sourcePath = str(value, "sourcePath");
  const sourceSha256 = str(value, "sourceSha256");
  const region = validateRegionProvenance(value);
  const extractedOn = str(value, "extractedOn");
  const sourceByteLength = num(value, "sourceByteLength");
  const extractorVersion = num(value, "extractorVersion");

  if (
    repository === null ||
    branch === null ||
    commitSha === null ||
    commitDate === null ||
    sourcePath === null ||
    sourceSha256 === null ||
    region === null ||
    extractedOn === null ||
    sourceByteLength === null ||
    extractorVersion === null
  ) {
    return null;
  }
  // A pinned artifact must name a real commit and a real file hash. A branch
  // name or a placeholder here would mean the authority is not actually pinned.
  if (!/^[0-9a-f]{40}$/.test(commitSha)) return null;
  if (!/^[0-9a-f]{64}$/.test(sourceSha256)) return null;

  const conditionalCompilation = validateConditionalCompilation(value["conditionalCompilation"]);
  if (conditionalCompilation === undefined) return null;
  const pinnedExtraction = validatePinnedExtraction(value);
  if (pinnedExtraction === undefined) return null;

  return {
    ...(conditionalCompilation === null ? {} : { conditionalCompilation }),
    repository,
    branch,
    commitSha,
    commitDate,
    sourcePath,
    sourceSha256,
    sourceByteLength,
    ...region,
    extractedOn,
    extractorVersion,
    ...(pinnedExtraction === null ? {} : pinnedExtraction),
  };
}

const PINNED_EXTRACTION_KEYS = [
  "regionSha256",
  "livePtrPolicy",
  "dispatchSource",
  "inertStatements",
  "methodPrologue",
  "spellGatedActions",
];
const SHA256_HEX = /^[0-9a-f]{64}$/;

/**
 * The M11-D2-C extraction record, when present. `null` when none of its
 * fields is present (every earlier artifact), `undefined` when any is present
 * and the record is partial or malformed — a half-recorded tie-back is
 * refused rather than read as whichever half looks usable.
 */
function validatePinnedExtraction(value: Record<string, unknown>):
  | {
      readonly regionSha256: string;
      readonly livePtrPolicy: AuthorityLivePtrPolicy;
      readonly dispatchSource: { readonly sourcePath: string; readonly sourceSha256: string };
      readonly inertStatements?: readonly AuthorityInertStatement[];
      readonly methodPrologue?: AuthorityMethodPrologue;
      readonly spellGatedActions?: readonly AuthoritySpellGatedAction[];
    }
  | null
  | undefined {
  if (!PINNED_EXTRACTION_KEYS.some((key) => key in value)) return null;
  const regionSha256 = str(value, "regionSha256");
  const livePtrPolicy = AUTHORITY_LIVE_PTR_POLICIES.find((policy) => policy === value["livePtrPolicy"]);
  const dispatchRaw = value["dispatchSource"];
  if (regionSha256 === null || !SHA256_HEX.test(regionSha256) || livePtrPolicy === undefined)
    return undefined;
  if (!isRecord(dispatchRaw) || Object.keys(dispatchRaw).length !== 2) return undefined;
  const dispatchPath = str(dispatchRaw, "sourcePath");
  const dispatchSha256 = str(dispatchRaw, "sourceSha256");
  if (dispatchPath === null || dispatchSha256 === null || !SHA256_HEX.test(dispatchSha256)) return undefined;
  const dispatchSource = { sourcePath: dispatchPath, sourceSha256: dispatchSha256 };
  const methodPrologue = validateMethodPrologue(value["methodPrologue"]);
  const spellGatedActions = validateSpellGatedActions(value["spellGatedActions"]);
  if (methodPrologue === undefined || spellGatedActions === undefined) return undefined;
  const methodForms = {
    ...(methodPrologue === null ? {} : { methodPrologue }),
    ...(spellGatedActions === null ? {} : { spellGatedActions }),
  };
  if (!("inertStatements" in value)) return { regionSha256, livePtrPolicy, dispatchSource, ...methodForms };
  const inertRaw = value["inertStatements"];
  if (!Array.isArray(inertRaw) || inertRaw.length === 0) return undefined;
  const inertStatements: AuthorityInertStatement[] = [];
  for (const raw of inertRaw) {
    if (!isRecord(raw)) return undefined;
    const sourceLine = num(raw, "sourceLine");
    const statement = str(raw, "statement");
    const identifier = str(raw, "identifier");
    if (sourceLine === null || !Number.isInteger(sourceLine) || sourceLine < 1) return undefined;
    if (statement === null || identifier === null || !CPP_IDENTIFIER.test(identifier)) return undefined;
    if (!statement.includes(identifier)) return undefined;
    inertStatements.push({ sourceLine, statement, identifier });
  }
  return { regionSha256, livePtrPolicy, dispatchSource, inertStatements, ...methodForms };
}

/** The prologue record: `null` when absent, `undefined` when present and malformed. */
function validateMethodPrologue(value: unknown): AuthorityMethodPrologue | null | undefined {
  if (value === undefined) return null;
  if (!isRecord(value)) return undefined;
  const startLine = num(value, "startLine");
  const endLine = num(value, "endLine");
  const appliesWhen = str(value, "appliesWhen");
  if (startLine === null || endLine === null || appliesWhen === null || appliesWhen.length === 0)
    return undefined;
  if (!Number.isInteger(startLine) || !Number.isInteger(endLine) || startLine < 1 || endLine < startLine) {
    return undefined;
  }
  return { startLine, endLine, appliesWhen };
}

/** The spell-gated records: `null` when absent, `undefined` when present and malformed. */
function validateSpellGatedActions(value: unknown): readonly AuthoritySpellGatedAction[] | null | undefined {
  if (value === undefined) return null;
  if (!Array.isArray(value) || value.length === 0) return undefined;
  const actions: AuthoritySpellGatedAction[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return undefined;
    const sourceLine = num(raw, "sourceLine");
    const statement = str(raw, "statement");
    const spellName = str(raw, "spellName");
    const emitted = raw["emitted"];
    if (sourceLine === null || !Number.isInteger(sourceLine) || sourceLine < 1) return undefined;
    if (statement === null || spellName === null || !statement.includes(spellName)) return undefined;
    if (!(emitted === null || (typeof emitted === "string" && emitted.length > 0))) return undefined;
    actions.push({ sourceLine, statement, spellName, emitted });
  }
  return actions;
}

const NAMESPACE_FUNCTION_SELECTOR_KEYS = ["kind", "enclosingNamespace", "functionHeader", "playerIdentifier"];
const CLASS_METHOD_SELECTOR_KEYS = ["kind", "enclosingClass", "functionHeader"];
const INCLUDED_FILE_SELECTOR_KEYS = [
  "kind",
  "includingSourcePath",
  "includingSourceSha256",
  "includeLine",
  "functionHeader",
];
const CPP_IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;

/**
 * The region provenance in exactly one of its two forms, or `null`.
 *
 * The form is decided by the PRESENCE of `regionSelector`: absent, both marker
 * fields must be non-empty strings (the pre-M11-C1a form, unchanged); present,
 * neither marker field may appear and the selector must be complete, of a
 * known kind, and carry no other key. Mixed or partial provenance is refused
 * rather than read as whichever half looks usable.
 */
function validateRegionProvenance(value: Record<string, unknown>): AuthorityRegionProvenance | null {
  if (!("regionSelector" in value)) {
    const regionStartMarker = str(value, "regionStartMarker");
    const regionEndMarker = str(value, "regionEndMarker");
    if (regionStartMarker === null || regionEndMarker === null) return null;
    return { regionStartMarker, regionEndMarker };
  }
  if ("regionStartMarker" in value || "regionEndMarker" in value) return null;
  const selector = value["regionSelector"];
  if (!isRecord(selector)) return null;
  if (selector["kind"] === "CLASS_METHOD") {
    if (Object.keys(selector).some((key) => !CLASS_METHOD_SELECTOR_KEYS.includes(key))) return null;
    const enclosingClass = str(selector, "enclosingClass");
    const methodHeader = str(selector, "functionHeader");
    if (enclosingClass === null || methodHeader === null || !CPP_IDENTIFIER.test(enclosingClass)) return null;
    if (methodHeader.trim() !== methodHeader || !methodHeader.includes(`${enclosingClass}::`)) return null;
    return { regionSelector: { kind: "CLASS_METHOD", enclosingClass, functionHeader: methodHeader } };
  }
  if (selector["kind"] === "INCLUDED_FILE") {
    if (Object.keys(selector).some((key) => !INCLUDED_FILE_SELECTOR_KEYS.includes(key))) return null;
    const includingSourcePath = str(selector, "includingSourcePath");
    const includingSourceSha256 = str(selector, "includingSourceSha256");
    const includeLine = str(selector, "includeLine");
    const includedHeader = str(selector, "functionHeader");
    if (
      includingSourcePath === null ||
      includingSourceSha256 === null ||
      includeLine === null ||
      includedHeader === null
    ) {
      return null;
    }
    if (!/^[0-9a-f]{64}$/.test(includingSourceSha256) || !includeLine.startsWith("#include ")) return null;
    return {
      regionSelector: {
        kind: "INCLUDED_FILE",
        includingSourcePath,
        includingSourceSha256,
        includeLine,
        functionHeader: includedHeader,
      },
    };
  }
  if (Object.keys(selector).some((key) => !NAMESPACE_FUNCTION_SELECTOR_KEYS.includes(key))) return null;
  if (selector["kind"] !== "NAMESPACE_FUNCTION") return null;
  const enclosingNamespace = str(selector, "enclosingNamespace");
  const functionHeader = str(selector, "functionHeader");
  const playerIdentifier = str(selector, "playerIdentifier");
  if (enclosingNamespace === null || functionHeader === null || playerIdentifier === null) return null;
  if (!CPP_IDENTIFIER.test(enclosingNamespace) || !CPP_IDENTIFIER.test(playerIdentifier)) return null;
  if (functionHeader.trim() !== functionHeader) return null;
  return {
    regionSelector: { kind: "NAMESPACE_FUNCTION", enclosingNamespace, functionHeader, playerIdentifier },
  };
}

/**
 * The guard record, when present. `null` when the field is absent (no guard
 * in the region), `undefined` when it is present and malformed.
 */
function validateConditionalCompilation(value: unknown): AuthorityConditionalCompilation | null | undefined {
  if (value === undefined) return null;
  if (!isRecord(value)) return undefined;
  const clientVersion = str(value, "clientVersion");
  const guardsRaw = value["guards"];
  if (clientVersion === null || !Array.isArray(guardsRaw)) return undefined;
  const guards: AuthorityVersionGuardRecord[] = [];
  for (const raw of guardsRaw) {
    if (!isRecord(raw)) return undefined;
    const line = num(raw, "line");
    const form = str(raw, "form");
    const comparison = str(raw, "comparison");
    const guardClientVersion = str(raw, "clientVersion");
    const holds = raw["holds"];
    const statementsEmitted = num(raw, "statementsEmitted");
    const statementsDropped = num(raw, "statementsDropped");
    const endLine = raw["endLine"];
    if (
      line === null ||
      (form !== "IF" && form !== "ELSE_IF") ||
      comparison === null ||
      guardClientVersion === null ||
      typeof holds !== "boolean" ||
      statementsEmitted === null ||
      statementsDropped === null ||
      !(endLine === null || (typeof endLine === "number" && Number.isFinite(endLine)))
    ) {
      return undefined;
    }
    guards.push({
      line,
      form,
      comparison,
      clientVersion: guardClientVersion,
      holds,
      statementsEmitted,
      statementsDropped,
      endLine,
    });
  }
  return { clientVersion, guards };
}

/** Field names that must NOT appear on an action: they are derived, not stored. */
export const FORBIDDEN_DERIVED_ACTION_KEYS = [
  "actionToken",
  "conditionRaw",
  "callsListName",
  "entryKind",
] as const;

export function validateAuthorityArtifact(value: unknown): ArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");

  const artifactVersion = num(value, "artifactVersion");
  if (artifactVersion !== SUPPORTED_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${String(artifactVersion)} is not ${SUPPORTED_ARTIFACT_VERSION}`,
    );
  }

  const authorityId = str(value, "authorityId");
  const artifactRevision = str(value, "artifactRevision");
  const entryListName = str(value, "entryListName");
  const specRaw = value["spec"];
  if (authorityId === null || artifactRevision === null || entryListName === null || !isRecord(specRaw)) {
    return invalid("NOT_AN_OBJECT", "artifact header fields are missing or malformed");
  }
  const className = str(specRaw, "className");
  const specName = str(specRaw, "specName");
  if (className === null || specName === null) {
    return invalid("NOT_AN_OBJECT", "spec is malformed");
  }

  const provenance = validateProvenance(value["provenance"]);
  if (provenance === null) {
    return invalid(
      "MALFORMED_PROVENANCE",
      "provenance is incomplete, commitSha/sourceSha256 is not a hash, or the region provenance is not exactly one of the marker-line or namespace-function forms",
    );
  }

  const listsRaw = value["lists"];
  if (!Array.isArray(listsRaw) || listsRaw.length === 0) {
    return invalid("MALFORMED_LISTS", "lists is not a non-empty array");
  }

  const lists: AuthorityArtifactList[] = [];
  const seenListNames = new Set<string>();
  for (const listRaw of listsRaw) {
    if (!isRecord(listRaw)) return invalid("MALFORMED_LISTS", "a list entry is not an object");
    const listName = str(listRaw, "listName");
    const receiverIdentifier = str(listRaw, "receiverIdentifier");
    const actionsRaw = listRaw["actions"];
    if (listName === null || receiverIdentifier === null || !Array.isArray(actionsRaw)) {
      return invalid("MALFORMED_LISTS", "a list entry is missing listName, receiverIdentifier or actions");
    }
    if (seenListNames.has(listName)) {
      return invalid("DUPLICATE_LIST_NAME", listName);
    }
    seenListNames.add(listName);

    const actions: AuthorityArtifactAction[] = [];
    for (let index = 0; index < actionsRaw.length; index += 1) {
      const actionRaw = actionsRaw[index];
      if (!isRecord(actionRaw)) return invalid("MALFORMED_ACTION", `${listName}[${index}] is not an object`);
      for (const forbidden of FORBIDDEN_DERIVED_ACTION_KEYS) {
        if (forbidden in actionRaw) {
          return invalid(
            "MALFORMED_ACTION",
            `${listName}[${index}] stores derived field '${forbidden}'; derived fields must be computed from actionStringVerbatim`,
          );
        }
      }
      const actionStringVerbatim = str(actionRaw, "actionStringVerbatim");
      const priorityOrdinal = num(actionRaw, "priorityOrdinal");
      const sourceLine = num(actionRaw, "sourceLine");
      if (actionStringVerbatim === null || priorityOrdinal === null || sourceLine === null) {
        return invalid("MALFORMED_ACTION", `${listName}[${index}] is missing required fields`);
      }
      if (priorityOrdinal !== index) {
        return invalid(
          "MALFORMED_ACTION",
          `${listName}[${index}] has priorityOrdinal ${priorityOrdinal}; ordinals must match array order`,
        );
      }
      const commentRaw = actionRaw["comment"];
      const comment = typeof commentRaw === "string" ? commentRaw : null;
      actions.push({ priorityOrdinal, actionStringVerbatim, comment, sourceLine });
    }
    lists.push({ listName, receiverIdentifier, actions });
  }

  if (!seenListNames.has(entryListName)) {
    return invalid("ENTRY_LIST_MISSING", entryListName);
  }

  return {
    ok: true,
    artifact: {
      artifactVersion,
      authorityId,
      artifactRevision,
      spec: { className, specName },
      entryListName,
      provenance,
      lists,
    },
  };
}
